# Generated by build.py from recipe.yml for recipe imap-share-a-folder-between-mailboxes. Do not edit.
set -e
cd "$(dirname "$0")"
awk '{printf "%s\r\n", $0}' > rota.eml <<'EOF'
From: ann@example.com
To: team@example.com
Subject: On-call rota for December

Bob takes the first week.
EOF
surl --mail-domain example.com --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass --mailbox carol@example.com:carolpass --group oncall=bob@example.com,carol@example.com --shared-folder team=ann@example.com,bob@example.com --shared-folder ops=@oncall imap://127.0.0.1:8080/ &
sleep 1
curl -sS -u ann@example.com:annpass -T rota.eml imap://127.0.0.1:8080/Shared/team --next -sS -u bob@example.com:bobpass "imap://127.0.0.1:8080/Shared/team;UID=1"
kill $(jobs -p)
